window.products.push({"id":493132,"name":"Nostalgia HAP8RR Hot Air Popcorn Maker","category":"homeandappliances","retail price":59.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81OVmRY3dJL._AC_SL1500_.jpg","description":"Make healthy, oil-free popcorn anytime with a beautifully designed retro popper! it features a longer popcorn chute that better guides popped popcorn into your bowl, along with a unique popping chamber designed to create a swirling airflow, resulting in more popped kernels. Use the pre-measured cap to make up to 8-cups of popcorn per batch. Cord wrap allows for tidy storage.","images":["https://m.media-amazon.com/images/I/81OVmRY3dJL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Nostalgia","source_asin":"B0744KQD2P","category_path":"Home & Kitchen"},"sku":"BM-493132","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0744KQD2P","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0744KQD2P","price_pending":true,"merchant_ready":false});
